fun main(): void {
  args = Environ.args().collect(Array);
  // tools/probe.py executes the binary without arguments after compilation.
  if (args.size() == 1) { print_string("failure driver compiled; select old|new and a case"); return };
  assert(args.size() == 3 && (args[1] == "old" || args[1] == "new"));
  SKStore.withRegionVoid(() ~> f_parity_environment_failure(args[1] == "old", args[2]))
}

Probe.sk:
// Same isolated-restore pattern as tests/Support/RewriteProbe.sk, plus exact
// primitive/array-write counts. Wall-clock timing is deliberately not compared.
fun f_parity_environment_probeCompare(
  label: String, saved: LeanExecutionCheckpoint,
  original: (mutable LeanExecution) ~> LeanValue,
  replacement: (mutable LeanExecution) ~> LeanValue,
  expected: ?LeanValue = None(),
): (LeanValue, LeanExecutionCheckpoint) {
  oldRuntime = saved.restoreRaw();
  newRuntime = saved.restoreRaw();
  oldResult = original(oldRuntime);
  newResult = replacement(newRuntime);
  if (native_eq(oldResult, newResult) != 0) leanFail("environment result mismatch: " + label);
  if (native_eq(oldRuntime.checkpoint().refs, newRuntime.checkpoint().refs) != 0) leanFail("environment reference mismatch: " + label);
  assert(oldRuntime.primitiveCount == newRuntime.primitiveCount);
  assert(oldRuntime.arrayWriteCount == newRuntime.arrayWriteCount);
  assert(oldRuntime.arrayWriteElements == newRuntime.arrayWriteElements);
  expected match {
  | Some(value) -> if (native_eq(newResult, value) != 0) leanFail("environment independent expectation failed: " + label)
  | None() -> void
  };
  (newResult, newRuntime.checkpoint())
}

